const sq = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";

async function sh(command, description) {
  const res = await tools.call({ name: "bash", arguments: { command, description, workdir: input.repoPath } });
  if (res.kind !== "foreground" || res.exitCode !== 0) {
    const detail = (res.stderr && res.stderr.text) || JSON.stringify(res);
    throw new Error("bash failed (" + description + "): " + detail);
  }
  return res.stdout.text;
}

if (typeof input.repoPath !== "string" || !input.repoPath) throw new Error("repoPath is required");
if (typeof input.commitMessage !== "string" || !input.commitMessage.trim()) throw new Error("commitMessage is required");
const requireNoRemotes = input.requireNoRemotes !== false;
const baselineRef = (typeof input.baselineRef === "string" && input.baselineRef) ? input.baselineRef : "main";

const remoteOut = (await sh("git remote -v", "List configured remotes")).trim();
const remotes = remoteOut ? remoteOut.split(/\r?\n/).map((l) => l.trim()).filter(Boolean) : [];
if (requireNoRemotes && remotes.length > 0) throw new Error("refusing to commit: git remotes configured: " + remotes.join("; "));
const branch = (await sh("git branch --show-current", "Show current branch")).trim();
if (!branch) throw new Error("detached HEAD or unknown branch; a checked-out branch is required");

const baselineSha = (await sh("git rev-parse " + sq(baselineRef), "Resolve baseline ref")).trim();

await sh("git add -A", "Stage all pending changes");
const stagedOut = (await sh("git diff --cached --name-status", "List staged file changes")).trim();
const stagedFiles = stagedOut
  ? stagedOut.split(/\r?\n/).filter(Boolean).map((l) => {
      const parts = l.split("\t");
      return { status: parts[0], path: parts.slice(1).join("\t") };
    })
  : [];
if (stagedFiles.length === 0) throw new Error("nothing to stage; no pending changes to commit");
if (Array.isArray(input.expectedChangedPaths)) {
  const actual = stagedFiles.map((f) => f.path).sort();
  const expected = input.expectedChangedPaths.map(String).sort();
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error("staged file set mismatch: got " + JSON.stringify(actual) + ", expected " + JSON.stringify(expected));
  }
}

await sh("git commit -m " + sq(input.commitMessage), "Create single local commit");
const commitSha = (await sh("git rev-parse HEAD", "Resolve new HEAD sha")).trim();
const parentSha = (await sh("git rev-parse HEAD^", "Resolve parent of new commit")).trim();
const subject = (await sh("git log -1 --format=%s", "Show commit subject")).trim();
if (subject !== input.commitMessage) throw new Error("commit subject mismatch: got '" + subject + "'");

const postStatus = (await sh("git status --porcelain", "Verify clean working tree")).trim();
const cleanTree = postStatus.length === 0;
if (!cleanTree) throw new Error("working tree not clean after commit: " + postStatus);
const countOut = (await sh("git rev-list --count " + sq(baselineSha + "..HEAD"), "Count commits after baseline")).trim();
const commitsAfterBaseline = parseInt(countOut, 10);
if (commitsAfterBaseline !== 1) throw new Error("expected exactly 1 commit after baseline, got " + commitsAfterBaseline);
if (parentSha !== baselineSha) throw new Error("commit parent does not match baseline: " + parentSha + " != " + baselineSha);

return { commitSha, parentSha, branch, stagedFiles, commitsAfterBaseline, cleanTree, remotes };
